cd "$ARCHON_HORIZON_ROOT" && "$HORIZON_BIN" roadmap list --focus AJC.picrep --json 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
items = d['items'] if isinstance(d,dict) and 'items' in d else d
def walk(it, depth=0):
    print('  '*depth + f\"{it.get('id')}  [{it.get('status')}] owner={it.get('owner') or '-'} ms={it.get('milestone') or '-'}\")
    for c in it.get('children',[]) or []: walk(c, depth+1)
for it in items: walk(it)
" 2>&1 | head -60

cd "$ARCHON_HORIZON_ROOT" && echo "=== AJC rows owned by live lanes ===" && "$HORIZON_BIN" roadmap list --json 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
live={'review-ajc','ajc-p1','ajc-p2','ajc-p3','ajc-p4'}
def walk(it):
    o=it.get('owner')
    if o and it.get('id','').startswith('AJC.'):
        tag='LIVE' if o in live else 'dead'
        print(f\"{tag}  {it.get('id')}  [{it.get('status')}] owner={o}\")
    for c in it.get('children',[]) or []: walk(c)
for it in d['items']: walk(it)
"
